<script lang="ts">let { data, form } = $props();</script>
<p class="eyebrow">Your profile</p><h1>Get paid your way.</h1><p class="muted">Your roommates see your primary payment details when they settle up.</p>
{#if form?.message}<p class="error" role="alert">{form.message}</p>{/if}{#if form?.success}<p class="success">{form.success}</p>{/if}
<section class="card"><h2>Payment methods</h2>{#each data.profiles as profile}<div class="method"><div><strong>{profile.method.toUpperCase()} {profile.isPrimary ? '· Primary' : ''}</strong><p>{profile.accountTitle} · {profile.accountNumber}</p>{#if profile.bankName}<p>{profile.bankName}</p>{/if}</div><div class="buttons">{#if !profile.isPrimary}<form method="POST" action="?/primary"><input type="hidden" name="id" value={profile.id} /><button>Make primary</button></form>{/if}<form method="POST" action="?/remove"><input type="hidden" name="id" value={profile.id} /><button>Remove</button></form></div></div>{:else}<p class="muted">No payment methods yet.</p>{/each}</section>
<section class="card"><h2>Add payment method</h2><form method="POST" action="?/save" enctype="multipart/form-data"><label for="method">Method</label><select id="method" name="method"><option value="raast">Raast</option><option value="easypaisa">EasyPaisa</option><option value="jazzcash">JazzCash</option><option value="nayapay">NayaPay</option><option value="bank">Bank transfer</option></select><label for="title">Account title</label><input id="title" name="accountTitle" required maxlength="100" /><label for="number">Account number / mobile / IBAN</label><input id="number" name="accountNumber" required maxlength="80" /><label for="bank">Bank name (bank transfer only)</label><input id="bank" name="bankName" /><label for="qr">QR image (optional)</label><input id="qr" type="file" name="qr" accept="image/png,image/jpeg,image/webp" /><button class="button submit">Save method</button></form></section>
<section class="card"><h2>WhatsApp link</h2>{#if data.whatsappJid}<p>Linked: {data.whatsappJid}</p>{:else}<p class="muted">Generate a one-time code, then send <strong>/link CODE</strong> to the bot in your hostel group. The code expires in 10 minutes.</p><form method="POST" action="?/link"><button class="button">Generate link code</button></form>{#if form?.code}<p class="code" role="status">/link {form.code}</p>{/if}{/if}</section>
<style>.eyebrow{text-transform:uppercase;letter-spacing:.13em;color:#0b806b;font-weight:800;font-size:12px}.card{max-width:700px;margin:20px 0}.method{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #e7eee8;padding:14px 0}.method p{margin:3px 0;color:#647b75}.buttons{display:flex;gap:5px}.buttons form{margin:0}.buttons button{border:0;background:#e6f1ea;border-radius:8px;padding:8px;color:#18584b}.submit{margin-top:20px}.code{font-size:22px;font-weight:850;letter-spacing:.04em;color:#0b806b}.success{color:#147a53}</style>
